const translationTextOriginals = new WeakMap<Text, string>();
const translationAttributeOriginals = new WeakMap<Element, Record<string, string>>();

function translationDictionaries(language: Language) {
  return [
    translations[language], workspaceTranslations[language], productExtraTranslations[language], rawProductTranslations[language],
    productUiTranslations[language], additionalProductUiTranslations[language], prescriptionTranslations[language], finalProductUiTranslations[language],
    lastUiTranslations[language], placeholderTranslations[language], formFinalTranslations[language], variantTranslations[language], labelTranslations[language],
    orderExtraTranslations[language], finalOrderTranslations[language], guideRawTranslations[language], guideUiTranslations[language], finalGuideTranslations[language],
  ];
}

function translateKnownSellerCopy(language: Language) {
  if (typeof document === 'undefined') return () => undefined;
  const englishToItalian = new Map<string, string>();
  Object.entries({ ...remainingSellerTranslations.en, ...remainingSellerEnumTranslations.en, ...remainingSellerExtraTranslations.en }).forEach(([key, value]) => {
    const translated = remainingSellerTranslations.it[key] ?? remainingSellerEnumTranslations.it[key] ?? remainingSellerExtraTranslations.it[key];
    if (translated) englishToItalian.set(value, translated);
  });
  translationDictionaries('en').forEach((dictionary, index) => {
    const italianDictionary = translationDictionaries('it')[index];
    Object.entries(dictionary).forEach(([key, value]) => {
      const translated = italianDictionary[key];
      if (translated) englishToItalian.set(value, translated);
    });
  });
  const italianToEnglish = new Set(englishToItalian.values());
  const phraseTranslations: Array<[string, string]> = [
    ['Loading\u00e2\u20ac\u00a6', 'Caricamento…'], ['Saving\u00e2\u20ac\u00a6', 'Salvataggio…'], ['Deleting\u00e2\u20ac\u00a6', 'Eliminazione…'], ['Adding\u00e2\u20ac\u00a6', 'Aggiunta…'],
    ['Approval:', 'Approvazione:'], ['Payment:', 'Pagamento:'], ['Budget:', 'Budget:'], ['used', 'utilizzati'], ['remaining', 'rimanenti'],
    ['fixed off', 'di sconto fisso'], ['priority', 'priorità'], ['events', 'eventi'], ['Stock:', 'Scorte:'], ['in stock', 'disponibile'],
    ['Approved', 'Approvato'], ['Not approved', 'Non approvato'], ['No reason supplied.', 'Nessun motivo fornito.'], ['User #', 'Utente n.'],
    ['System', 'Sistema'], ['Before', 'Prima'], ['After', 'Dopo'], ['Ads reserve', 'Riserva annunci'], ['Total', 'Totale'],
    ['Selected product #', 'Prodotto selezionato n.'], ['select the product to confirm eligibility.', 'seleziona il prodotto per confermare l’idoneità.'], ['Up to €', 'Fino a €'],
    ['Your Seller Wallet needs', 'Al Portafoglio venditore mancano'], ['I authorize reserving', 'Autorizzo la prenotazione di'], ['Run immediately after admin approval', 'Avvia subito dopo approvazione amministratore'],
    ['per UTC day', 'al giorno UTC'], ['in stock', 'disponibile'], ['Ends', 'Fine'], ['Starts', 'Inizio'], ['Status', 'Stato'], ['Approval', 'Approvazione'], ['Discount', 'Sconto'], ['Analytics', 'Analisi'], ['Campaign', 'Campagna'], ['Actions', 'Azioni'], ['Performance', 'Prestazioni'], ['Description', 'Descrizione'], ['Destination', 'Destinazione'], ['Schedule', 'Programmazione'], ['Run now', 'Avvia ora'], ['Save campaign', 'Salva campagna'], ['Create campaign', 'Crea campagna'], ['Edit', 'Modifica'], ['Delete', 'Elimina'], ['Pause', 'Metti in pausa'], ['Resume', 'Riprendi'], ['Submit', 'Invia'], ['Order total', 'Totale ordine'], ['Delivery', 'Consegna'], ['Payment', 'Pagamento'], ['View Details', 'Visualizza dettagli'], ['Featured', 'In evidenza'], ['Inactive', 'Inattivo'], ['Active', 'Attivo'], ['Muted', 'Silenziato'], ['Inventory', 'Inventario'], ['Catalogue', 'Catalogo'], ['Followers', 'Follower'], ['Products', 'Prodotti'], ['Orders', 'Ordini'], ['Reviews', 'Recensioni'], ['Support', 'Supporto'],
  ];
  const replacementPairs = [...englishToItalian.entries().filter(([english]) => english.length > 8 && english.includes(' ')), ...phraseTranslations]
    .sort((left, right) => right[0].length - left[0].length);
  const normalize = (value: string) => value.replace(/\s+/g, ' ').trim();
  const update = (root: Node) => {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    const textNodes: Text[] = [];
    let node: Node | null;
    while ((node = walker.nextNode())) textNodes.push(node as Text);
    textNodes.forEach((textNode) => {
      const parent = textNode.parentElement;
      if (!parent || parent.closest('.notranslate, script, style, noscript')) return;
      const current = textNode.nodeValue || '';
      const original = translationTextOriginals.get(textNode);
      if (!original || (normalize(current) !== normalize(original) && !italianToEnglish.has(normalize(current)))) {
        translationTextOriginals.set(textNode, current);
      }
      const source = translationTextOriginals.get(textNode) || current;
      const leading = source.match(/^\s*/)?.[0] || '';
      const trailing = source.match(/\s*$/)?.[0] || '';
      const body = normalize(source);
      let translated = language === 'it' ? englishToItalian.get(body) : body;
      if (language === 'it' && !translated) {
        translated = replacementPairs.reduce((value, [english, italian]) => value.replaceAll(english, italian), body);
        translated = translated
          .replace(/^Page (\d+) of (\d+)$/, 'Pagina $1 di $2')
          .replace(/^Campaign #(\d+)/, 'Campagna n. $1')
          .replace(/^Order #(\d+)/, 'Ordine n. $1')
          .replace(/^Starts immediately →/, 'Inizia subito →')
          .replace(/^Schedule timezone:/, 'Fuso orario programmazione:');
      }
      if (translated && translated !== body) textNode.nodeValue = `${leading}${translated}${trailing}`;
      else if (language === 'en' && current !== source) textNode.nodeValue = source;
    });
    if (root instanceof Element || root instanceof Document) {
      root.querySelectorAll<HTMLElement>('[placeholder], [aria-label], [title]').forEach((element) => {
        if (element.closest('.notranslate')) return;
        const originals = translationAttributeOriginals.get(element) || {};
        ['placeholder', 'aria-label', 'title'].forEach((attribute) => {
          const current = element.getAttribute(attribute);
          if (current == null) return;
          if (!originals[attribute] || (current !== originals[attribute] && !italianToEnglish.has(normalize(current)))) originals[attribute] = current;
          const source = originals[attribute];
          const translated = language === 'it' ? englishToItalian.get(normalize(source)) : source;
          if (translated && translated !== current) element.setAttribute(attribute, translated);
          else if (language === 'en' && current !== source) element.setAttribute(attribute, source);
        });
        translationAttributeOriginals.set(element, originals);
      });
    }
  };
  update(document.body);
  let applying = false;
  const observer = new MutationObserver((mutations) => {
    if (applying) return;
    applying = true;
    mutations.forEach((mutation) => {
      if (mutation.type === 'characterData' && mutation.target.parentElement) update(mutation.target.parentElement);
      mutation.addedNodes.forEach((added) => update(added));
    });
    applying = false;
  });
  observer.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['placeholder', 'aria-label', 'title'] });
  return () => observer.disconnect();
}

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<Language>('en');
  useEffect(() => { const saved = localStorage.getItem(STORAGE_KEY); if (saved === 'en' || saved === 'it') setLanguageState(saved); }, []);
  useEffect(() => { localStorage.setItem(STORAGE_KEY, language); document.documentElement.lang = language; }, [language]);
  useEffect(() => translateKnownSellerCopy(language), [language]);
  const setLanguage = useCallback((next: Language) => setLanguageState(next), []);
  const toggleLanguage = useCallback(() => setLanguageState((current) => current === 'en' ? 'it' : 'en'), []);
  const t = useCallback((key: string, variables: Variables = {}) => {
    const resolvedKey = legacyKeyAliases[key] ?? key;
    const value = translations[language][resolvedKey] ?? workspaceTranslations[language][resolvedKey] ?? productExtraTranslations[language][resolvedKey] ?? rawProductTranslations[language][resolvedKey] ?? productUiTranslations[language][resolvedKey] ?? additionalProductUiTranslations[language][resolvedKey] ?? prescriptionTranslations[language][resolvedKey] ?? finalProductUiTranslations[language][resolvedKey] ?? lastUiTranslations[language][resolvedKey] ?? placeholderTranslations[language][resolvedKey] ?? formFinalTranslations[language][resolvedKey] ?? variantTranslations[language][resolvedKey] ?? labelTranslations[language][resolvedKey] ?? orderExtraTranslations[language][resolvedKey] ?? finalOrderTranslations[language][resolvedKey] ?? guideRawTranslations[language][resolvedKey] ?? guideUiTranslations[language][resolvedKey] ?? finalGuideTranslations[language][resolvedKey] ?? translations.en[resolvedKey] ?? workspaceTranslations.en[resolvedKey] ?? productExtraTranslations.en[resolvedKey] ?? rawProductTranslations.en[resolvedKey] ?? productUiTranslations.en[resolvedKey] ?? additionalProductUiTranslations.en[resolvedKey] ?? prescriptionTranslations.en[resolvedKey] ?? finalProductUiTranslations.en[resolvedKey] ?? lastUiTranslations.en[resolvedKey] ?? placeholderTranslations.en[resolvedKey] ?? formFinalTranslations.en[resolvedKey] ?? variantTranslations.en[resolvedKey] ?? labelTranslations.en[resolvedKey] ?? orderExtraTranslations.en[resolvedKey] ?? finalOrderTranslations.en[resolvedKey] ?? guideRawTranslations.en[resolvedKey] ?? guideUiTranslations.en[resolvedKey] ?? finalGuideTranslations.en[resolvedKey] ?? resolvedKey;
    return value.replace(/\{(\w+)\}/g, (_, name: string) => String(variables[name] ?? `{${name}}`));
  }, [language]);
  const value = useMemo(() => ({ language, setLanguage, toggleLanguage, t }), [language, setLanguage, toggleLanguage, t]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error('useLanguage must be used within a LanguageProvider');
  return context;
}
